class LoginPage extends ConsumerStatefulWidget { final bool isAdminLogin; const LoginPage({super.key,this.isAdminLogin=false}); @override ConsumerState<LoginPage> createState()=>_LoginPageState(); }
class _LoginPageState extends ConsumerState<LoginPage>{final _formKey=GlobalKey<FormState>();final _phoneController=TextEditingController();bool _telegramStarting=false;
@override void dispose(){_phoneController.dispose();super.dispose();}
String _normalizePhone(){var p=_phoneController.text.trim().replaceAll(RegExp(r'\s+'),'');if(p.startsWith('+964'))p=p.substring(4);if(p.startsWith('964'))p=p.substring(3);if(p.startsWith('0'))p=p.substring(1);return '964$p';}
Future<void> _telegramLogin() async {if(_telegramStarting||!(_formKey.currentState?.validate()??false))return;setState(()=>_telegramStarting=true);try{final phone=_normalizePhone();final data=await ref.read(authControllerProvider.notifier).startTelegramLogin(phone);final token=data['request_token'] as String;final url=data['telegram_url'] as String;if(!await launchUrl(Uri.parse(url),mode:LaunchMode.externalApplication))throw Exception('تعذر فتح Telegram. تأكد من تثبيت التطبيق ثم حاول مرة أخرى.');if(!mounted)return;await _waitForTelegramLogin(token);}catch(e){if(!mounted)return;final m=e.toString().replaceFirst('Exception: ','');if(m.contains('مرتبط بحساب')||m.contains('duplicate key')||m.contains('profiles_telegram_user_id_uidx')){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('هذا الحساب مرتبط بحساب آخر في تطبيق استشارة.')));}else{ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(m),backgroundColor:Theme.of(context).colorScheme.error));}}finally{if(mounted)setState(()=>_telegramStarting=false);}}
Future<void> _waitForTelegramLogin(String token) async {if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('جارٍ التحقق من حساب Telegram...')));for(var i=0;i<30;i++){await Future<void>.delayed(const Duration(seconds:2));if(!mounted)return;try{await ref.read(authControllerProvider.notifier).verifyTelegramLogin(requestToken:token,code:'');if(mounted)return;}catch(e){final m=e.toString().replaceFirst('Exception: ','');if(m.contains('مرتبط بحساب')||m.contains('duplicate key')||m.contains('profiles_telegram_user_id_uidx')){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('هذا الحساب مرتبط بحساب آخر في تطبيق استشارة.')));return;}if(m.contains('رمز التحقق غير صحيح')||m.contains('افتح Telegram'))continue;throw Exception(m);}}if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('انتهت مهلة التحقق. أعد المحاولة.')));}
Future<void> _showTelegramCodeDialog(String token) async {final c=TextEditingController();var verifying=false;try{await showDialog<void>(context:context,barrierDismissible:false,builder:(dc)=>StatefulBuilder(builder:(context,setState)=>AlertDialog(title:const Text('رمز Telegram',textAlign:TextAlign.right),content:Column(mainAxisSize:MainAxisSize.min,crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('تم فتح Telegram. اضغط «بدء» وسيصلك رمز تحقق من 6 أرقام.',textAlign:TextAlign.right),const SizedBox(height:16),TextField(controller:c,keyboardType:TextInputType.number,textDirection:TextDirection.ltr,maxLength:6,decoration:const InputDecoration(labelText:'رمز التحقق',hintText:'123456',border:OutlineInputBorder())]),actions:[TextButton(onPressed:verifying?null:()=>Navigator.of(dc).pop(),child:const Text('إلغاء')),FilledButton(onPressed:verifying?null:()async{if(!RegExp(r'^\d{6}$').hasMatch(c.text.trim())){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('أدخل رمز التحقق المكون من 6 أرقام')));return;}setState(()=>verifying=true);try{await ref.read(authControllerProvider.notifier).verifyTelegramLogin(requestToken:token,code:c.text.trim());if(dc.mounted)Navigator.of(dc).pop();}catch(e){setState(()=>verifying=false);if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ','')),backgroundColor:Theme.of(context).colorScheme.error));}},child:verifying?const SizedBox(width:20,height:20,child:CircularProgressIndicator(strokeWidth:2)):const Text('تحقق ودخول'))]}));}finally{c.dispose();}}
@override Widget build(BuildContext context){final scheme=Theme.of(context).colorScheme;final state=ref.watch(authControllerProvider);final accent=AppColors.primary;return Scaffold(backgroundColor:scheme.surface,body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.fromLTRB(24,30,24,34),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:520),child:Form(key:_formKey,child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Container(width:78,height:78,alignment:Alignment.center,decoration:BoxDecoration(color:AppColors.primaryContainer,borderRadius:BorderRadius.circular(26)),child:const Icon(Icons.balance_rounded,size:42,color:AppColors.goldLight)),const SizedBox(height:24),Text(widget.isAdminLogin?'دخول الإدارة':'مرحباً بك في استشارة',textAlign:TextAlign.center,style:TextStyle(fontSize:28,fontWeight:FontWeight.w900,color:scheme.onSurface)),const SizedBox(height:8),Text(widget.isAdminLogin?'سجل الدخول للوصول إلى لوحة الإدارة.':'سجّل الدخول برقم هاتفك واحصل على رمز التحقق داخل Telegram.',textAlign:TextAlign.center,style:TextStyle(color:scheme.onSurfaceVariant,fontSize:13.5,height:1.6)),const SizedBox(height:30),Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(color:scheme.surfaceContainerLowest,borderRadius:BorderRadius.circular(24),border:Border.all(color:scheme.outlineVariant)),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('رقم الهاتف',textAlign:TextAlign.right,style:TextStyle(fontWeight:FontWeight.w800,color:scheme.onSurface)),const SizedBox(height:9),TextFormField(controller:_phoneController,keyboardType:TextInputType.phone,textDirection:TextDirection.ltr,decoration:InputDecoration(hintText:'07xxxxxxxx',prefixIcon:Icon(Icons.phone_android_rounded,color:accent),filled:true,fillColor:scheme.surfaceContainerLow,border:OutlineInputBorder(borderRadius:BorderRadius.circular(12))),validator:(v)=>v==null||v.trim().isEmpty?'رقم الهاتف مطلوب':null),const SizedBox(height:16),SizedBox(height:54,child:ElevatedButton.icon(onPressed:(_telegramStarting||state.isLoading)?null:_telegramLogin,icon:_telegramStarting?const SizedBox(width:20,height:20,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.send_rounded),label:Text(_telegramStarting?'جارٍ التحقق عبر Telegram...':'الدخول عبر Telegram',style:const TextStyle(fontWeight:FontWeight.w800)))),const SizedBox(height:10),Text('إذا كان حساب Telegram مرتبطاً بحسابك، سيتم تسجيل الدخول تلقائياً بعد التحقق.',textAlign:TextAlign.center,style:TextStyle(fontSize:11,color:scheme.onSurfaceVariant,height:1.5))])),const SizedBox(height:18),OutlinedButton.icon(onPressed:state.isLoading||_telegramStarting?null:()=>ref.read(authControllerProvider.notifier).signInWithGoogle(),icon:const Icon(Icons.g_mobiledata_rounded,size:30,color:AppColors.primary),label:const Text('المتابعة باستخدام Google')),const SizedBox(height:22),Text('باستمرارك، أنت توافق على شروط الاستخدام وسياسة الخصوصية.',textAlign:TextAlign.center,style:TextStyle(fontSize:10.5,color:scheme.onSurfaceVariant,height:1.55))]))))));}}
